class Solution {
    private int[][] memo;
    private int[] valid;
    public int maxStudents(char[][] seats) {
        int m = seats.length, n = seats[0].length;
        memo = new int[m + 1][1 << n];
        for (int[] row : memo) Arrays.fill(row, -1);
        valid = new int[m];
        for (int r = 0; r < m; ++r) {
            int mask = 0;
            for (int c = 0; c < n; ++c) {
                if (seats[r][c] == '.') mask |= (1 << c);
            }
            valid[r] = mask;
        }
        return dfs(0, 0, m, n);
    }
    private int dfs(int row, int prevMask, int m, int n) {
        if (row == m) return 0;
        if (memo[row][prevMask] != -1) return memo[row][prevMask];
        int ans = 0;
        int rowMask = valid[row];
        int sub = rowMask;
        while (true) {
            if ((sub & (sub << 1)) == 0) {
                if ((sub & (prevMask << 1)) == 0 && (sub & (prevMask >> 1)) == 0) {
                    ans = Math.max(ans, Integer.bitCount(sub) + dfs(row + 1, sub, m, n));
                }
            }
            if (sub == 0) break;
            sub = (sub - 1) & rowMask;
        }
        return memo[row][prevMask] = ans;
    }
}

var maxStudents = function(seats) {
    const m = seats.length, n = seats[0].length;
    const memo = Array.from({ length: m + 1 }, () => new Int32Array(1 << n).fill(-1));
    const valid = new Int32Array(m);
    for (let r = 0; r < m; ++r) {
        let mask = 0;
        for (let c = 0; c < n; ++c) {
            if (seats[r][c] === '.') mask |= (1 << c);
        }
        valid[r] = mask;
    }
    function countBits(x) {
        let cnt = 0;
        while (x > 0) {
            cnt += x & 1;
            x >>= 1;
        }
        return cnt;
    }
    function dfs(row, prevMask) {
        if (row === m) return 0;
        if (memo[row][prevMask] !== -1) return memo[row][prevMask];
        let ans = 0;
        const rowMask = valid[row];
        let sub = rowMask;
        while (true) {
            if (!(sub & (sub << 1))) {
                if (!(sub & (prevMask << 1)) && !(sub & (prevMask >> 1))) {
                    ans = Math.max(ans, countBits(sub) + dfs(row + 1, sub));
                }
            }
            if (sub === 0) break;
            sub = (sub - 1) & rowMask;
        }
        return memo[row][prevMask] = ans;
    }
    return dfs(0, 0);
};
